<?php
declare(strict_types=1);namespace App\Repository;use App\Entity\NewsPost;use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;use Doctrine\Persistence\ManagerRegistry;/** @extends ServiceEntityRepository<NewsPost> */final class NewsPostRepository extends ServiceEntityRepository{public function __construct(ManagerRegistry $r){parent::__construct($r,NewsPost::class);}/** @return list<NewsPost> */public function published(?\DateTimeImmutable $at=null):array{$at??=new \DateTimeImmutable('now',new \DateTimeZone('Europe/Berlin'));return $this->createQueryBuilder('n')->andWhere('n.published = true')->andWhere('(n.visibleFrom IS NULL OR n.visibleFrom <= :at)')->andWhere('(n.visibleUntil IS NULL OR n.visibleUntil >= :at)')->setParameter('at',$at)->orderBy('n.publishedAt','DESC')->getQuery()->getResult();}}
